-- ============================================================
-- Noor AlDhikr V81.6 FREE AI
-- مساعد معرفي مجاني بالكامل: لا OpenAI API ولا Edge Function مطلوبة.
-- آمن لإعادة التشغيل ولا يحذف بياناتك الحالية.
-- ============================================================

begin;

create table if not exists public.ai_knowledge (
  id uuid primary key default gen_random_uuid(),
  knowledge_key text not null default gen_random_uuid()::text unique,
  category text not null default 'عام',
  title text not null check(length(title) between 2 and 240),
  answer text not null check(length(answer) between 2 and 12000),
  keywords text[] not null default '{}',
  priority integer not null default 100 check(priority between 0 and 1000),
  active boolean not null default true,
  updated_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.ai_knowledge enable row level security;

drop policy if exists ai_knowledge_public_read on public.ai_knowledge;
drop policy if exists ai_knowledge_owner_all on public.ai_knowledge;

create policy ai_knowledge_public_read on public.ai_knowledge
for select to anon,authenticated
using(active=true or public.is_owner());

create policy ai_knowledge_owner_all on public.ai_knowledge
for all to authenticated
using(public.is_owner()) with check(public.is_owner());

grant select on public.ai_knowledge to anon,authenticated;
grant insert,update,delete on public.ai_knowledge to authenticated;
grant all on public.ai_knowledge to service_role;

do $$ begin
  create trigger ai_knowledge_touch before update on public.ai_knowledge
  for each row execute function public.touch_updated_at();
exception when duplicate_object then null; end $$;

do $$ begin
  create trigger audit_ai_knowledge after insert or update or delete on public.ai_knowledge
  for each row execute function public.audit_owner_change();
exception when duplicate_object then null; end $$;

insert into public.ai_knowledge(knowledge_key,category,title,answer,keywords,priority,active) values
('freeai-about','عام','ما الذي يستطيع المساعد فعله؟','المساعد يعمل مجانًا من قاعدة معرفة نور الذكر التي يديرها مالك الموقع، ويبحث أيضًا في محتوى القسم المفتوح. يمكنه المساعدة في الأذكار والقرآن والرقية والأسئلة العامة عن أقسام الموقع. لا يرسل أسئلتك إلى OpenAI أو أي مزود ذكاء اصطناعي مدفوع.',array['ماذا تستطيع','مساعدة','المساعد','كيف تستخدم','مجاني'],250,true),
('dhikr-mutlaq-muqayyad','الأذكار','الفرق بين الذكر المطلق والذكر المقيد','الذكر المطلق هو ما لم يُربط في النص بوقت أو حال أو عدد مخصوص، فيُشرع في أوقات واسعة. والذكر المقيد هو ما ورد مرتبطًا بسبب أو وقت أو حال معيّن؛ كأذكار الصباح والمساء وأذكار ما بعد الصلاة. الأفضل في الذكر المقيد المحافظة على الصيغة والوقت والعدد الوارد قدر الاستطاعة.',array['الذكر المطلق','الذكر المقيد','مطلق','مقيد','الفرق بين الذكر'],300,true),
('adhkar-morning-evening','الأذكار','وقت أذكار الصباح والمساء','أذكار الصباح مرتبطة بأول النهار، وأذكار المساء بآخره. توجد سعة عند أهل العلم في تحديد بداية الوقت ونهايته؛ فاحرص على قراءتها في وقتها المعتاد، وإن فاتتك فلا تجعل الخلاف في التوقيت سببًا لترك الذكر.',array['أذكار الصباح','اذكار الصباح','أذكار المساء','اذكار المساء','وقت الصباح','وقت المساء'],260,true),
('adhkar-counts','الأذكار','الأعداد الواردة في الأذكار','إذا ورد الذكر بعدد محدد فالأفضل المحافظة على العدد الوارد، وإذا كان الذكر مطلقًا بلا عدد مخصوص فلا يلزم عدد بعينه. لا تجعل العد سببًا للوسوسة؛ المقصود الذكر مع حضور القلب قدر الاستطاعة.',array['عدد الذكر','كم مرة','ثلاث مرات','مائة مرة','تكرار الذكر'],210,true),
('ruqyah-definition','الرقية','ما هي الرقية الشرعية؟','الرقية الشرعية تكون بقراءة القرآن والأدعية والأذكار المشروعة مع التوكل على الله، من غير طلاسم أو ألفاظ مجهولة أو تعلق بغير الله. يستطيع الإنسان أن يرقي نفسه، مع عدم ترك العلاج الطبي عند وجود أعراض تحتاج تقييمًا صحيًا.',array['الرقية','رقيه','أرقي نفسي','ارقي نفسي','رقية شرعية'],300,true),
('ruqyah-self','الرقية','كيف أرقي نفسي؟','يمكنك أن تقرأ على نفسك الفاتحة وما تيسر من القرآن والأذكار والأدعية المشروعة، وتنـفث نفثًا خفيفًا وتمسح على نفسك إن تيسر. حافظ على الصلاة والأذكار، واجتنب الطلاسم والممارسات المجهولة. وإذا وجدت أعراضًا صحية أو نفسية مستمرة فاطلب تقييمًا مختصًا أيضًا.',array['كيف أرقي نفسي','ارقي نفسي','رقية النفس','الرقية على النفس'],280,true),
('ruqyah-recording','الرقية','الرقية المسجلة','سماع القرآن والرقية المسجلة قد يكون نافعًا من جهة الاستماع للقرآن والطمأنينة، لكنه لا يجعل التسجيل بديلًا لازمًا عن قراءة الإنسان لنفسه والدعاء والتوكل. لا تربط الشفاء بجهاز أو تسجيل بعينه.',array['رقية مسجلة','الرقية المسجلة','سماع الرقية','تشغيل الرقية'],170,true),
('symptoms-not-proof','السلامة','هل الأعراض تثبت السحر أو العين أو المس؟','لا يمكن إثبات السحر أو العين أو المس بمجرد أعراض عامة؛ فكثير من الأعراض لها أسباب صحية أو نفسية أو حياتية. يمكنك المحافظة على الأذكار والرقية المشروعة، ومع الأعراض المستمرة أو الشديدة يُنصح بمراجعة مختص صحي وعدم اتهام أحد بناءً على الظن.',array['هل عندي سحر','هل فيا سحر','أعراض السحر','اعراض السحر','عين','حسد','مس','علامات السحر'],400,true),
('hasad-safe','السلامة','الحسد والعين','الإيمان بوجود العين والحسد لا يعني أن كل تعب أو مشكلة سببهما. لا يمكن للموقع أن يجزم بسبب غيبي لحالة شخص. حافظ على الأذكار والدعاء والرقية المشروعة، وتعامل مع الأسباب الصحية والنفسية والاجتماعية بجدية أيضًا.',array['الحسد','العين','محسود','مصاب بالعين'],260,true),
('dream-bad','الأحلام','التعامل مع الحلم المزعج','إذا رأيت ما تكره فاستعذ بالله من شرها، ولا تجعل المنام أساسًا لقرار مصيري أو اتهام شخص. تفسير الأحلام ظني وليس يقينًا، وقد تكون الأحلام من حديث النفس أو مما يشغل الإنسان.',array['حلم مزعج','كابوس','رؤيا سيئة','حلم سيئ','خفت من حلم'],270,true),
('dream-interpretation','الأحلام','هل يمكن الجزم بتفسير الحلم؟','لا. تعبير الرؤى اجتهادي وظني، وليس وسيلة لمعرفة الغيب أو إصدار أحكام مؤكدة على الأشخاص والمستقبل. إذا كان المنام يقلقك، ركز على ما ينفعك في الواقع ولا تبنِ قرارًا خطيرًا عليه.',array['تفسير حلم','فسر حلمي','معنى المنام','تعبير الرؤيا'],260,true),
('health-safe','السلامة','الأعراض الصحية','لا يستطيع المساعد تشخيص حالة طبية من الأعراض وحدها. إذا كان العرض شديدًا أو جديدًا أو مستمرًا، أو صاحبه خطر مثل ألم صدر شديد أو صعوبة تنفس أو فقد وعي، فاطلب رعاية طبية مناسبة فورًا. الأذكار والرقية دعم روحي وليستا بديلًا عن التقييم الطبي.',array['عرض صحي','أعراض','اعراض','مرض','دوخة','ألم','صداع','تعب'],400,true),
('waswas-safe','السلامة','الوسواس والقلق','الوسواس والقلق قد يسببان أفكارًا وأعراضًا مزعجة، ولا يصح الجزم بأنهما دليل على سبب غيبي. حاول تقليل التحقق المتكرر والبحث المرهق عن العلامات، وحافظ على الأذكار، وإذا أثّر القلق أو الوسواس على حياتك فمراجعة مختص نفسي قد تكون مفيدة.',array['وسواس','قلق','افكار ملحة','أفكار ملحة','خوف مستمر'],300,true),
('quran-memorize','القرآن','طريقة عملية لحفظ القرآن','اختر مقدارًا صغيرًا ثابتًا، اقرأه بتأنٍ عدة مرات، اربط آخر آية بأول التالية، ثم استظهر دون نظر، وراجع القديم يوميًا قبل إضافة جديد. الاستمرار على مقدار قليل أفضل من اندفاع كبير ينقطع.',array['حفظ القرآن','الحفظ','أحفظ','احفظ','مراجعة القرآن','تثبيت الحفظ'],260,true),
('quran-reading','القرآن','البدء في قراءة القرآن','ابدأ بالاستعاذة عند القراءة، واقرأ بتدبر وعلى قدر استطاعتك. إذا كان هدفك المواظبة فحدد وردًا واقعيًا صغيرًا وثابتًا، ثم زد تدريجيًا بدل أن تبدأ بمقدار يصعب الاستمرار عليه.',array['قراءة القرآن','ابدأ القرآن','ورد القرآن','كيف اقرأ القرآن'],190,true),
('prayer-times','الصلاة','مواقيت الصلاة في الموقع','مواقيت الصلاة تعتمد على الموقع الجغرافي وطريقة الحساب. اختر موقعك بدقة داخل الموقع، وإذا لاحظت فرقًا معتبرًا مع التقويم الرسمي في بلدك فاعتمد الجهة المحلية الموثوقة لمواقيت الصلاة.',array['مواقيت الصلاة','وقت الصلاة','الصلاة القادمة','موعد الصلاة'],220,true),
('qibla','القبلة','تحديد القبلة','ميزة القبلة في الهاتف تعتمد على إذن الموقع وحساسات الجهاز وقد تتأثر بالمجالات المغناطيسية. ابتعد عن المعادن الكبيرة، حرّك الهاتف لمعايرة البوصلة، وقارن باتجاه معروف إذا كنت غير مطمئن.',array['القبلة','اتجاه القبلة','البوصلة','تحديد القبلة'],180,true),
('tasbeeh','المسبحة','استخدام المسبحة داخل الموقع','المسبحة أداة للعد والتنظيم فقط. يمكنك استخدامها للأذكار التي تريد عدها، مع الانتباه إلى أن الأذكار المقيدة بعدد يُحافظ فيها على العدد الوارد، أما الذكر المطلق فلا يحتاج إلى عدد معين.',array['المسبحة','عداد الذكر','التسبيح','سبحة'],150,true),
('memorization-tests','الحفظ','اختبارات الحفظ','استخدم اختبارات الحفظ بعد المراجعة لا قبلها فقط: اختبر مقطعًا قصيرًا، سجّل الأخطاء، ارجع للمصحف وصححها، ثم أعد الاختبار بعد فترة. الهدف كشف مواضع الضعف لا مجرد الحصول على نتيجة مرتفعة.',array['اختبار الحفظ','اختبارات الحفظ','امتحان القرآن','نتيجة الحفظ'],180,true),
('dua-general','الأذكار','الدعاء والذكر','ادعُ الله بما تحتاج من خير الدنيا والآخرة بألفاظ صحيحة ومعانٍ مشروعة، ولا يلزم أن يكون كل دعاء بصيغة محفوظة ما لم يكن المقام مرتبطًا بذكر مأثور مخصوص. واحرص على الأدعية الثابتة لما فيها من جوامع المعاني.',array['الدعاء','ادعي','أدعي','دعاء معين'],170,true)
on conflict(knowledge_key) do nothing;

update public.ai_settings
set enabled=true,
    assistant_name='مساعد نور الذكر المجاني',
    function_name='local-free',
    model_label='V81.7 Local Knowledge',
    system_prompt='لم أجد إجابة دقيقة في قاعدة المعرفة الحالية. جرّب صياغة السؤال بشكل أبسط، أو اطلب من مالك الموقع إضافة هذا الموضوع إلى قاعدة المعرفة من لوحة المالك.',
    safety_notice='مساعد معرفي مجاني. لا يقدّم تشخيصًا طبيًا، ولا يجزم بسبب غيبي، ولا يقدّم تفسيرًا قطعيًا للأحلام أو حكمًا شرعيًا قطعيًا في موضع الخلاف.',
    max_daily_per_user=200,
    temperature=0.35,
    quick_prompts='["ما الفرق بين الذكر المطلق والمقيد؟","كيف أرقي نفسي؟","متى أقرأ أذكار الصباح؟","هل الأعراض تثبت السحر أو العين؟","كيف أثبت حفظ القرآن؟"]'::jsonb,
    updated_at=now()
where id=true;

update public.site_modules
set enabled=true,nav_visible=true,label='المساعد الذكي المجاني',updated_at=now()
where module_key='aiAssistant';

commit;

select
  'V81.7 FREE AI READY' as status,
  (select count(*) from public.ai_knowledge) as knowledge_items,
  (select enabled from public.ai_settings where id=true) as ai_enabled,
  (select model_label from public.ai_settings where id=true) as engine,
  (select enabled from public.site_modules where module_key='aiAssistant') as module_enabled;
